from pathlib import Path
s=Path('check_clique_proof.py').read_text()
s=s.replace('def verify(catalogue, proof_path, target):','def verify(catalogue, proof_path, target, root_limit):')
s=s.replace('        roots = 0\n', '        assert 0 < root_limit <= sum(i == r for i, r in enumerate(representatives))\n        roots = 0\n        last_root = None\n')
s=s.replace('            roots += 1\n', '            roots += 1\n            last_root = i\n            if roots == root_limit:\n                break\n')
s=s.replace("        assert stream.read(8) == b'ENDPROOF', 'missing completion marker'\n        assert stream.read(1) == b'', 'trailing proof data'", "        assert roots == root_limit\n        consumed_trace_bytes = stream.tell()\n        # This is deliberately a restricted-root check, with no claim about\n        # unvisited roots or the unread remainder of the supplied trace.")
s=s.replace("return {'verified': True, 'order': n, 'excluded_clique_size': target,", "return {'verified': True, 'scope': 'specified initial canonical roots only',\n            'order': n, 'excluded_size_in_these_roots': target,\n            'last_root_catalogue_index': last_root, 'consumed_trace_bytes': consumed_trace_bytes,")
s=s.replace("    args = ap.parse_args()\n    print(json.dumps(verify(args.catalogue, args.proof, args.target), indent=2))", "    ap.add_argument('root_limit', type=int)\n    args = ap.parse_args()\n    print(json.dumps(verify(args.catalogue, args.proof, args.target, args.root_limit), indent=2))")
s=s.replace('"""Check a streamed clique refutation using stdlib only.', '"""Check ONLY a specified initial set of D4 roots, using stdlib only.\n\nThis never claims global nonexistence and deliberately ignores later trace data.')
Path('check_clique_prefix.py').write_text(s)
s=Path('check_trace.cpp').read_text()
s=s.replace(' int n,m,target,words;', ' int root_limit=0,last_root=-1;\n int n,m,target,words;')
s=s.replace('selection={i};node(candidates,target-1);roots++;', 'selection={i};node(candidates,target-1);roots++;last_root=i;if(root_limit && roots==(uint64_t)root_limit)break;')
s=s.replace('  for(char c:string("ENDPROOF"))', '''  if(root_limit){require(roots==(uint64_t)root_limit,"not enough canonical roots");cout<<"{\\\"verified\\\":true,\\\"scope\\\":\\\"specified initial canonical roots only\\\",\\\"order\\\":"<<n<<",\\\"excluded_size_in_these_roots\\\":"<<target<<",\\\"roots\\\":"<<roots<<",\\\"last_root_catalogue_index\\\":"<<last_root<<",\\\"nodes\\\":"<<nodes<<",\\\"seconds\\\":"<<seconds()<<"}\\n";return;}\n  for(char c:string("ENDPROOF"))''')
s=s.replace('require(argc==4,"usage: check_trace catalogue trace.gz target");Trace trace(argv[2]);Audit audit(argv[1],stoi(argv[3]),trace);audit.run();', 'require(argc==5,"usage: check_root_prefix catalogue trace.gz target roots");Trace trace(argv[2]);Audit audit(argv[1],stoi(argv[3]),trace);audit.root_limit=stoi(argv[4]);require(audit.root_limit>0,"positive root count required");audit.run();')
Path('check_root_prefix.cpp').write_text('// RESTRICTED ROOT VERIFIER: never a global exclusion claim.\n'+s)
